const CreateOfficeHoursScheduleRequestSchema = z
  .object({
    name: z
      .string()
      .openapi({
        description:
          "The name of the office hours schedule. It must be unique among the workspace's schedules; a duplicate name returns a 422 error.",
        example: 'Standard Support Hours',
      }),
    time_zone_name: z
      .string()
      .exactOptional()
      .openapi({
        description:
          "The IANA time zone the schedule's hours are evaluated in. Optional; defaults to the workspace's time zone.",
        example: 'America/New_York',
      }),
    time_intervals: z
      .array(OfficeHoursTimeIntervalSchema)
      .openapi({
        description:
          "The open intervals for the schedule. `start_minute` and `end_minute` must be on a 15-minute boundary, except for the whole-week interval `0` to `10079`. Don't send `day_of_week`; it is read-only and a request that includes it is rejected with a 400 error.",
      }),
  })
  .openapi({
    title: 'Create Office Hours Schedule Request',
    description:
      'The request payload for creating an office hours schedule. Any other field, apart from `id`, is rejected with a 400 error.',
    required: ['name', 'time_intervals'],
  })
  .openapi('CreateOfficeHoursScheduleRequest')

const UpdateOfficeHoursScheduleRequestSchema = z
  .object({
    name: z
      .string()
      .exactOptional()
      .openapi({
        description:
          "The name of the office hours schedule. It must be unique among the workspace's schedules; a duplicate name returns a 422 error.",
        example: 'Extended Support Hours',
      }),
    time_zone_name: z
      .string()
      .exactOptional()
      .openapi({
        description: "The IANA time zone the schedule's hours are evaluated in.",
        example: 'America/New_York',
      }),
    time_intervals: z
      .array(OfficeHoursTimeIntervalSchema)
      .exactOptional()
      .openapi({
        description:
          "The open intervals for the schedule. `start_minute` and `end_minute` must be on a 15-minute boundary, except for the whole-week interval `0` to `10079`. Don't send `day_of_week`; it is read-only and a request that includes it is rejected with a 400 error. When provided, the intervals replace all of the schedule's existing intervals.",
      }),
  })
  .openapi({
    title: 'Update Office Hours Schedule Request',
    description:
      'The request payload for updating an office hours schedule. Only the provided fields are updated. Any other field, apart from `id`, is rejected with a 400 error.',
    required: [],
  })
  .openapi('UpdateOfficeHoursScheduleRequest')

const OfficeHoursExceptionSchema = z
  .object({
    type: z
      .string()
      .exactOptional()
      .openapi({
        description: 'The type of the object - always `office_hours_exception`.',
        example: 'office_hours_exception',
      }),
    id: z
      .string()
      .exactOptional()
      .openapi({
        description: 'The unique identifier for the office hours exception.',
        example: '456',
      }),
    office_hours_schedule_id: z
      .string()
      .exactOptional()
      .openapi({
        description: 'The unique identifier for the schedule this exception belongs to.',
        example: '123',
      }),
    exception_date: z.iso
      .date()
      .exactOptional()
      .openapi({
        description: 'The date the exception applies to, in `YYYY-MM-DD` format.',
        example: '2026-12-25',
      }),
    exception_type: z
      .enum(['closed', 'custom_hours'])
      .exactOptional()
      .openapi({
        description:
          '`closed` means the workspace is closed all day; `custom_hours` replaces the regular hours with `time_intervals`.',
        example: 'closed',
      }),
    name: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({ description: 'An optional name for the exception.', example: 'Christmas Day' }),
    time_intervals: z
      .array(OfficeHoursTimeIntervalSchema)
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'The open intervals for the exception date. `null` when `exception_type` is `closed`.',
      }),
    recurring_annually: z
      .boolean()
      .exactOptional()
      .openapi({
        description: 'Whether the exception repeats every year on the same date.',
        example: true,
      }),
    created_at: z
      .int()
      .exactOptional()
      .openapi({
        description: 'The time the exception was created as a Unix timestamp.',
        example: 1717200000,
      }),
    updated_at: z
      .int()
      .exactOptional()
      .openapi({
        description: 'The time the exception was last updated as a Unix timestamp.',
        example: 1717200000,
      }),
  })
  .openapi({
    title: 'Office Hours Exception',
    'x-tags': ['Office Hours'],
    description:
      "An exception overrides a schedule's regular hours on a specific date, such as a public holiday.",
    required: [],
  })
  .openapi('OfficeHoursException')

