const FinAgentMessageSchema = z
  .object({
    author: z
      .enum(['user', 'agent', 'fin'])
      .openapi({
        description:
          'The author that created the message. In `conversation_metadata.history`, only `user` and `agent` are accepted.',
        example: 'user',
      }),
    body: z
      .string()
      .openapi({
        description:
          "The body of the message. Accepts both plain text and HTML format.\nFor the message you send to Fin, this is the user's message. For an `agent` item in `conversation_metadata.history`, it is the agent's message.\nFin's response is returned in the format set by `response_format` (HTML by default).\n",
        example: 'How can I see my account details?',
      }),
    timestamp: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({
        description:
          'The timestamp when the message was created.\nUsed to deduplicate messages sent within a 5 minute window.\nIdeally should include milliseconds for higher precision.\nSend `timestamp` or `timestamp_ms`; at least one is required. If you send both, `timestamp_ms` is used.\nOn the top-level `message`, sending neither fails with a 422 error (`message: timestamp_ms is required`). In `conversation_metadata.history`, an item with neither causes the whole history to be ignored.\n',
        example: '2025-01-24T10:01:20.000Z',
      }),
    timestamp_ms: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({
        description:
          'The timestamp when the message was created, with millisecond precision.\nAccepted in place of `timestamp` when you send a message, and also present in webhook event responses (fin_replied). At least one of `timestamp` or `timestamp_ms` is required.\n',
        example: '2025-01-24T10:01:20.456Z',
      }),
  })
  .openapi({
    title: 'Fin Agent Message',
    description: 'A message exchanged within a Fin Agent conversation.',
    'x-tags': ['Fin Agent'],
    required: ['author', 'body'],
  })
  .openapi('FinAgentMessage')

