const HitlEventSchema = z
  .object({
    hitl_cycle_id: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'Identifies the consultation this event belongs to. The same on every event of one consultation, so it is not unique per event.',
        example: '3f2a91c4-8e77-4d61-9a2b-0c5d7e1f4a80',
      }),
    event_type: z
      .enum([
        'fin_consultation_started',
        'fin_draft_proposed',
        'fin_teammate_input_received',
        'fin_draft_revised',
        'fin_consultation_finished',
      ])
      .exactOptional()
      .openapi({ description: 'What happened.', example: 'fin_consultation_started' }),
    conversation_part_id: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description: 'The conversation part this event relates to, where one exists.',
        example: '4471002',
      }),
    rule_id: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'The escalation rule that triggered the consultation, as recorded when it began. Null if no rule triggered it.',
        example: '88',
      }),
    rule_name: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          "The rule's name as recorded when the consultation began, which may differ from its current name.",
        example: 'Refunds over $100',
      }),
    created_at: z
      .int()
      .exactOptional()
      .openapi({
        description:
          'Unix timestamp for when the event occurred. Approximate on `fin_draft_proposed`.',
        example: 1767225600,
      }),
    data: z
      .object({
        channel: z
          .enum(['email', 'chat', 'voice', 'unknown'])
          .exactOptional()
          .openapi({
            description: 'The channel the conversation was on when Fin consulted a teammate.',
            example: 'email',
          }),
        rule_threshold_percent: z
          .int()
          .nullable()
          .exactOptional()
          .openapi({
            description: 'The confidence threshold the rule required, as a percentage.',
            example: 60,
          }),
        confidence_percent: z
          .int()
          .nullable()
          .exactOptional()
          .openapi({
            description:
              'How confident Fin was in its answer, as a percentage. Compare against `rule_threshold_percent`.',
            example: 42,
          }),
        sharp_ask: z
          .string()
          .nullable()
          .exactOptional()
          .openapi({
            description: 'The question Fin put to the teammate.',
            example: 'How long do refunds take?',
          }),
        ask_rationale: z
          .string()
          .nullable()
          .exactOptional()
          .openapi({
            description: 'Why Fin needed to ask.',
            example: 'No article covers refund timelines.',
          }),
        issue_summary: z
          .string()
          .nullable()
          .exactOptional()
          .openapi({
            description: "Fin's summary of what the customer needs.",
            example: 'Customer chasing a refund.',
          }),
        customer_question: z
          .string()
          .nullable()
          .exactOptional()
          .openapi({
            description: "The customer's message that prompted the consultation.",
            example: 'Where is my refund?',
          }),
        draft: z
          .string()
          .nullable()
          .exactOptional()
          .openapi({
            description: 'The reply Fin proposed to the teammate.',
            example: 'Refunds are processed within 30 days.',
          }),
        round_index: z
          .int()
          .exactOptional()
          .openapi({
            description: 'Which round of teammate feedback this event belongs to, starting at 1.',
            example: 1,
          }),
        teammate_input: z
          .string()
          .nullable()
          .exactOptional()
          .openapi({
            description: 'The feedback the teammate gave Fin.',
            example: 'Tell them 5 business days.',
          }),
        reviewer_admin_id: z
          .string()
          .nullable()
          .exactOptional()
          .openapi({
            description:
              'The teammate involved in this event — who gave the feedback, or who approved the draft or took over.',
            example: '4001',
          }),
        regeneration_outcome: z
          .string()
          .nullable()
          .exactOptional()
          .openapi({
            description:
              'How Fin responded to the feedback. `answer` means it produced a revised draft, and is the only value accompanied by a `fin_draft_revised` event. `no_answer` means it had nothing to send, `failed` that regeneration failed, `consult_teammate` that it asked the teammate again, and `pending` that the consultation ended before Fin responded.',
            example: 'answer',
          }),
        revised_draft: z
          .string()
          .nullable()
          .exactOptional()
          .openapi({
            description: "The reply Fin produced after the teammate's feedback.",
            example: 'Refunds take 5 business days.',
          }),
        outcome: z
          .enum(['approved', 'taken_over', 'timed_out_sent', 'timed_out_escalated', 'superseded'])
          .exactOptional()
          .openapi({ description: 'How the consultation ended.', example: 'approved' }),
        approved_draft_type: z
          .enum(['original', 'revised'])
          .nullable()
          .exactOptional()
          .openapi({
            description:
              "Whether the teammate approved Fin's original draft or the one it revised after their feedback.",
            example: 'revised',
          }),
        final_draft: z
          .string()
          .nullable()
          .exactOptional()
          .openapi({
            description: 'The reply as it stood when the consultation ended.',
            example: 'Refunds take 5 business days.',
          }),
        sent_text: z
          .string()
          .nullable()
          .exactOptional()
          .openapi({
            description: 'What was sent to the customer. Null when nothing was sent.',
            example: 'Refunds take 5 business days.',
          }),
        duration_seconds: z
          .int()
          .nullable()
          .exactOptional()
          .openapi({ description: 'How long the consultation took, in seconds.', example: 180 }),
        rounds_count: z
          .int()
          .exactOptional()
          .openapi({
            description:
              'How many rounds of teammate feedback the consultation had. Only the ten most recent are returned as events, so this can exceed the number of `fin_teammate_input_received` events.',
            example: 1,
          }),
        payload_truncated: z
          .boolean()
          .exactOptional()
          .openapi({
            description:
              'Whether any text on this consultation was too long to store in full and was cut.',
            example: false,
          }),
      })
      .exactOptional()
      .openapi({
        description:
          'Fields specific to this event. Which are present depends on `event_type` — see the endpoint description for the full mapping.\n',
        required: [],
      }),
  })
  .openapi({
    title: 'HITL Event',
    description: 'A single event in a Fin human-in-the-loop consultation on a conversation.',
    required: [],
  })
  .openapi('HitlEvent')

