export const getExportReportingDataJobIdentifierRoute = createRoute({
  method: 'get',
  path: '/export/reporting_data/{job_identifier}',
  tags: ['Reporting Data Export'],
  summary: 'Get export job status',
  description: 'Requires the `export_reporting_data` OAuth scope.',
  request: {
    headers: z.object({
      'Intercom-Version': IntercomVersionSchema.openapi({
        param: {
          name: 'Intercom-Version',
          in: 'header',
          schema: { $ref: '#/components/schemas/intercom_version' },
          required: false,
        },
      }).exactOptional(),
    }),
    params: z.object({
      job_identifier: z
        .string()
        .openapi({
          param: {
            name: 'job_identifier',
            description: 'Unique identifier of the job.',
            in: 'path',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Job status returned successfully',
      content: {
        'application/json': {
          schema: z
            .object({
              job_identifier: z
                .string()
                .exactOptional()
                .openapi({ description: 'Unique identifier of the job.' }),
              status: z
                .enum(['pending', 'complete', 'failed'])
                .exactOptional()
                .openapi({ description: 'The status of the job.' }),
              download_url: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'The URL to download the export from. Empty until the job is complete.',
                }),
              download_expires_at: z
                .xor([
                  z
                    .preprocess(
                      (val) =>
                        typeof val === 'number' && Number.isSafeInteger(val)
                          ? BigInt(val)
                          : typeof val === 'string' && /^-?\d+$/.test(val)
                            ? BigInt(val)
                            : val,
                      z.int64(),
                    )
                    .openapi({ type: 'integer', format: 'int64' }),
                  z.string().max(0),
                ])
                .exactOptional()
                .openapi({
                  description:
                    'The time after which the export can no longer be downloaded, as a Unix timestamp in seconds. Empty string until the job is complete.',
                }),
            })
            .openapi({ required: [] }),
          examples: {
            'With pending status': {
              value: {
                job_identifier: 'job1',
                status: 'pending',
                download_url: '',
                download_expires_at: '',
              },
            },
            'With complete status': {
              value: {
                job_identifier: 'job1',
                status: 'complete',
                download_url: 'https://api.intercom.io/download/reporting_data/job1',
                download_expires_at: 1788480000,
              },
            },
            'With failed status': {
              value: {
                job_identifier: 'job1',
                status: 'failed',
                download_url: '',
                download_expires_at: '',
              },
            },
          },
        },
      },
    },
    400: {
      description: 'Bad Request',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            'Not available in this API version': {
              value: {
                type: 'error.list',
                request_id: 'b68959ea-6328-4f70-83cb-e7913dba1542',
                errors: [
                  {
                    code: 'intercom_version_invalid',
                    message: 'Requested resource is not available in current API version',
                  },
                ],
              },
            },
          },
        },
      },
    },
    401: UnauthorizedResponse,
    404: {
      description: 'When the job is not found or was created by a different teammate',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            'Not found': {
              value: {
                type: 'error.list',
                request_id: 'b68959ea-6328-4f70-83cb-e7913dba1542',
                errors: [
                  { code: 'not_found', message: 'Export job not found for identifier: job1' },
                ],
              },
            },
          },
        },
      },
    },
  },
})

