export const getDynamicContentsRoute = createRoute({
  method: 'get',
  path: '/dynamic_contents',
  tags: ['Dynamic Content'],
  summary: 'List all dynamic content',
  description:
    'You can fetch a list of all dynamic content for a workspace, most recently updated first.\n\nRequires the `read_dynamic_content` or `read_write_dynamic_content` OAuth scope.\n',
  operationId: 'listDynamicContents',
  request: {
    headers: z.object({
      'Intercom-Version': IntercomVersionSchema.openapi({
        param: {
          name: 'Intercom-Version',
          in: 'header',
          schema: { $ref: '#/components/schemas/intercom_version' },
          required: false,
        },
      }).exactOptional(),
    }),
    query: z.object({
      page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'page',
            in: 'query',
            required: false,
            description:
              'The page of results to fetch. Defaults to the first page. Values below 1 are treated as 1.',
            schema: { type: 'integer', example: 1 },
          },
          example: 1,
        }),
      per_page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().max(50),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'per_page',
            in: 'query',
            required: false,
            description:
              'The number of results to return per page. Defaults to 50. Values above 50 are reduced to 50, and values below 1 are treated as 1.',
            schema: { type: 'integer', maximum: 50, example: 20 },
          },
          example: 20,
        }),
    }),
  },
  responses: {
    200: {
      description: 'Successful response',
      content: {
        'application/json': {
          schema: DynamicContentListSchema,
          examples: {
            'Successful response': {
              value: {
                type: 'list',
                data: [
                  {
                    type: 'dynamic_content',
                    id: '123',
                    name: 'Support phone number',
                    key: 'support-phone-number',
                    content_type: 'inline',
                    default_locale: 'en',
                    variations: [
                      {
                        type: 'dynamic_content_variation',
                        id: '456',
                        locale: 'en',
                        brand_id: null,
                        text_content: '+1-555-0100',
                        json_blocks: null,
                        intentionally_empty: false,
                        created_at: 1663597223,
                        updated_at: 1663597223,
                      },
                    ],
                    created_at: 1663597223,
                    updated_at: 1663597223,
                  },
                ],
                total_count: 1,
                page: 1,
                per_page: 50,
                total_pages: 1,
              },
            },
          },
        },
      },
    },
    401: UnauthorizedResponse,
    403: {
      description: 'Dynamic content is not enabled',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            'Dynamic content is not enabled': {
              value: {
                type: 'error.list',
                request_id: '591a0c2f-78b3-41bb-bfa7-f1fae15107b9',
                errors: [
                  {
                    code: 'api_plan_restricted',
                    message: 'Dynamic content is not enabled for this workspace',
                  },
                ],
              },
            },
          },
        },
      },
    },
  },
})

