export const deleteCustomObjectInstancesCustomObjectTypeIdentifierRoute = createRoute({
  method: 'delete',
  path: '/custom_object_instances/{custom_object_type_identifier}',
  tags: ['Custom Object Instances'],
  summary: 'Delete a Custom Object Instance by External ID',
  description:
    'Delete a single Custom Object instance by external_id.\n\nRequires the `read_write_custom_object_instances` OAuth scope.\n',
  operationId: 'deleteCustomObjectInstancesByExternalId',
  request: {
    params: z.object({
      custom_object_type_identifier: z
        .string()
        .openapi({
          param: {
            name: 'custom_object_type_identifier',
            in: 'path',
            description:
              'The unique identifier of the custom object type that defines the structure of the custom object instance.',
            example: 'Order',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
    query: z
      .looseObject({})
      .transform((val) => {
        const rest: [string, unknown][] = []
        const groups = new Map<string, Record<string, unknown>>()
        const group = (name: string) => {
          const found = groups.get(name)
          if (found !== undefined) return found
          const made: Record<string, unknown> = Object.create(null)
          groups.set(name, made)
          return made
        }
        const spread = new Map<string, string[]>([['external_id', ['external_id']]])
        for (const [key, item] of Object.entries(val)) {
          const owners = spread.get(key)
          if (owners !== undefined) {
            for (const owner of owners) {
              group(owner)[key] = item
            }
            continue
          }
          rest.push([key, item])
        }
        return Object.fromEntries([...rest, ...groups])
      })
      .pipe(
        z.object({
          external_id: z
            .object({ external_id: z.string() })
            .openapi({
              param: {
                name: 'external_id',
                in: 'query',
                style: 'form',
                required: true,
                schema: {
                  type: 'string',
                  description:
                    'The unique identifier for the instance in the external system it originated from.',
                  title: 'Find by external_id',
                  properties: { external_id: { type: 'string' } },
                  required: ['external_id'],
                },
              },
              description:
                'The unique identifier for the instance in the external system it originated from.',
              title: 'Find by external_id',
              required: ['external_id'],
            }),
        }),
      ),
    headers: z.object({
      'Intercom-Version': IntercomVersionSchema.openapi({
        param: {
          name: 'Intercom-Version',
          in: 'header',
          schema: { $ref: '#/components/schemas/intercom_version' },
          required: false,
        },
      }).exactOptional(),
    }),
  },
  responses: {
    200: {
      description: 'successful',
      content: {
        'application/json': {
          schema: CustomObjectInstanceDeletedSchema,
          examples: { successful: { value: { id: '26', object: 'Order', deleted: true } } },
        },
      },
    },
    401: UnauthorizedResponse,
    404: {
      description: 'Custom object type or instance not found',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            'Instance not found': {
              value: {
                type: 'error.list',
                request_id: '9e4c1a86-3d75-42b9-8c60-5f1a7b93e2d4',
                errors: [{ code: 'not_found', message: 'Custom object instance not found' }],
              },
            },
            'Type not found': {
              value: {
                type: 'error.list',
                request_id: '2a7f5c93-8b14-46e0-97d2-3c6e1b85a07f',
                errors: [
                  { code: 'not_found', message: 'Custom object type `undefined` not found' },
                ],
              },
            },
          },
        },
      },
    },
  },
})

