export const getEventsRoute = createRoute({
  method: 'get',
  path: '/events',
  tags: ['Data Events'],
  summary: 'List all data events',
  description:
    "\n> 🚧\n>\n> Please note that you can only 'list' events that are less than 90 days old. Event counts and summaries will still include your events older than 90 days but you cannot 'list' these events individually if they are older than 90 days\n\nThe events belonging to a customer can be listed by sending a GET request to `https://api.intercom.io/events` with a user or lead identifier along with a `type` parameter. The identifier parameter can be one of `user_id`, `email`, `intercom_user_id` or `anonymous_id`. The `type` parameter value must be `user` or `lead`.\n\n- `https://api.intercom.io/events?type=user&user_id={user_id}`\n- `https://api.intercom.io/events?type=user&email={email}`\n- `https://api.intercom.io/events?type=user&intercom_user_id={id}` (this call can be used to list leads)\n\nWhen `type` is `lead`, a `user_id` you send is matched against the lead's anonymous id instead.\n\nThe `email` parameter value should be [url encoded](http://en.wikipedia.org/wiki/Percent-encoding) when sending.\n\nYou can optionally define the result page size as well with the `per_page` parameter.\n\nRequires the `read_events` or `write_events` OAuth scope.\n",
  operationId: 'lisDataEvents',
  request: {
    headers: z.object({
      'Intercom-Version': IntercomVersionSchema.openapi({
        param: {
          name: 'Intercom-Version',
          in: 'header',
          schema: { $ref: '#/components/schemas/intercom_version' },
          required: false,
        },
      }).exactOptional(),
    }),
    query: z.object({
      filter: z
        .xor([
          z
            .strictObject({ user_id: z.string() })
            .openapi({ title: 'user_id query parameter', required: ['user_id'] }),
          z
            .strictObject({ intercom_user_id: z.string() })
            .openapi({ title: 'intercom_user_id query parameter', required: ['intercom_user_id'] }),
          z
            .strictObject({ email: z.string() })
            .openapi({ title: 'email query parameter', required: ['email'] }),
          z
            .strictObject({ anonymous_id: z.string() })
            .openapi({ title: 'anonymous_id query parameter', required: ['anonymous_id'] }),
        ])
        .openapi({
          param: {
            in: 'query',
            name: 'filter',
            required: true,
            style: 'form',
            explode: true,
            schema: {
              type: 'object',
              oneOf: [
                {
                  title: 'user_id query parameter',
                  properties: { user_id: { type: 'string' } },
                  required: ['user_id'],
                  additionalProperties: false,
                },
                {
                  title: 'intercom_user_id query parameter',
                  properties: { intercom_user_id: { type: 'string' } },
                  required: ['intercom_user_id'],
                  additionalProperties: false,
                },
                {
                  title: 'email query parameter',
                  properties: { email: { type: 'string' } },
                  required: ['email'],
                  additionalProperties: false,
                },
                {
                  title: 'anonymous_id query parameter',
                  properties: { anonymous_id: { type: 'string' } },
                  required: ['anonymous_id'],
                  additionalProperties: false,
                },
              ],
            },
          },
        }),
      type: z
        .enum(['user', 'lead'])
        .openapi({
          param: {
            name: 'type',
            in: 'query',
            required: true,
            description: 'The value must be `user` or `lead`.',
            schema: { type: 'string', enum: ['user', 'lead'] },
          },
        }),
      per_page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'per_page',
            in: 'query',
            required: false,
            description: 'The number of events to return per page.',
            schema: { type: 'integer' },
          },
        }),
      since: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .exactOptional()
        .openapi({
          param: {
            name: 'since',
            in: 'query',
            required: false,
            description:
              'Only return events created after this time, as a Unix timestamp in milliseconds. Take the value from the `since` link in the `pages` object of a previous response.',
            schema: { type: 'integer', format: 'int64' },
          },
        }),
      before: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .exactOptional()
        .openapi({
          param: {
            name: 'before',
            in: 'query',
            required: false,
            description:
              'Only return events created before this time, as a Unix timestamp in milliseconds. Take the value from the `next` link in the `pages` object of a previous response.',
            schema: { type: 'integer', format: 'int64' },
          },
        }),
      summary: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            name: 'summary',
            in: 'query',
            required: false,
            description:
              'Set to `true` (or `1`) to return an event summary (`event.summary`) instead of the list of events. Omit for the paginated event list (`event.list`).',
            schema: { type: 'boolean' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Successful response',
      content: {
        'application/json': {
          schema: z.xor([DataEventListSchema, DataEventSummarySchema]),
          examples: {
            'Summary (summary=true)': {
              value: {
                type: 'event.summary',
                events: [],
                email: 'user26@email.com',
                intercom_user_id: '6762f22b1bb69f9f2193bc12',
                user_id: '3ecf64d0-9ed1-4e9f-88e1-da7d6e6782f3',
              },
            },
            'Event list (default)': {
              value: {
                type: 'event.list',
                events: [
                  {
                    type: 'event',
                    id: '2fc69404-91a6-11e7-be05-4fc6091e296e',
                    created_at: 1389913941,
                    event_name: 'invited-friend',
                    user_id: '314159',
                    email: 'frodo.baggins@example.com',
                    intercom_user_id: '63a0979a5eeebeaf28dd56ba',
                    metadata: {},
                  },
                ],
                pages: {
                  next: 'https://api.intercom.io/events?per_page=1&before=1389913941064&intercom_user_id=63a0979a5eeebeaf28dd56ba&type=user',
                  since:
                    'https://api.intercom.io/events?intercom_user_id=63a0979a5eeebeaf28dd56ba&type=user&since=1389913941065',
                },
              },
            },
          },
        },
      },
    },
    401: {
      description: 'Unauthorized',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            Unauthorized: {
              value: {
                type: 'error.list',
                request_id: 'e6f50446-be4a-40ac-8c8d-6fb91e1040fd',
                errors: [{ code: 'unauthorized', message: 'Access Token Invalid' }],
              },
            },
            'Token lacks required scope': {
              value: {
                type: 'error.list',
                request_id: 'b3a71f58-2c09-4e6d-91b7-4f8c5e2a0d63',
                errors: [
                  { code: 'token_unauthorized', message: 'Not authorized to access resource' },
                ],
              },
            },
          },
        },
      },
    },
    404: {
      description: 'Contact not found',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            'User not found': {
              value: {
                type: 'error.list',
                request_id: '5e9c0b24-71f3-4a86-bd50-2c7a1e638f49',
                errors: [{ code: 'not_found', message: 'User Not Found' }],
              },
            },
            'Lead not found': {
              value: {
                type: 'error.list',
                request_id: '93f6d205-4b18-47ea-8c31-6d0b5a7e2f14',
                errors: [{ code: 'not_found', message: 'Lead Not Found' }],
              },
            },
          },
        },
      },
    },
    422: {
      description: 'Unprocessable entity',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            'Unsupported type': {
              value: {
                type: 'error.list',
                request_id: '1d4e8a07-5f62-4390-b7c8-0a2e9b16d35f',
                errors: [{ code: 'parameter_invalid', message: 'unsupported type [company]' }],
              },
            },
          },
        },
      },
    },
  },
})

export const postEventsRoute = createRoute({
  method: 'post',
  path: '/events',
  tags: ['Data Events'],
  summary: 'Submit a data event',
  description:
    '\nYou will need an Access Token that has write permissions to send Events. Once you have a key you can submit events via POST to the Events resource, which is located at https://api.intercom.io/events, or you can send events using one of the client libraries. When working with the HTTP API directly a client should send the event with a `Content-Type` of `application/json`.\n\nWhen using the JavaScript API, [adding the code to your app](http://docs.intercom.io/configuring-Intercom/tracking-user-events-in-your-app) makes the Events API available. Once added, you can submit an event using the `trackEvent` method. This will associate the event with the Lead or currently logged-in user or logged-out visitor/lead and send it to Intercom. The final parameter is a map that can be used to send optional metadata about the event.\n\nWith the Ruby client you pass a hash describing the event to `Intercom::Event.create`, or call the `track_user` method directly on the current user object (e.g. `user.track_event`).\n\n**NB: For the JSON object types, please note that we do not currently support nested JSON structure.**\n\n| Type            | Description                                                                                                                                                                                                     | Example                                                                           |\n| :-------------- | :-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------- | :-------------------------------------------------------------------------------- |\n| String          | The value is a JSON String                                                                                                                                                                                      | `"source":"desktop"`                                                              |\n| Number          | The value is a JSON Number                                                                                                                                                                                      | `"load": 3.67`                                                                    |\n| Date            | The key ends with the String `_date` and the value is a [Unix timestamp](http://en.wikipedia.org/wiki/Unix_time), assumed to be in the [UTC](http://en.wikipedia.org/wiki/Coordinated_Universal_Time) timezone. | `"contact_date": 1392036272`                                                      |\n| Link            | The value is a HTTP or HTTPS URI.                                                                                                                                                                               | `"article": "https://example.org/ab1de.html"`                                     |\n| Rich Link       | The value is a JSON object that contains `url` and `value` keys.                                                                                                                                                | `"article": {"url": "https://example.org/ab1de.html", "value":"the dude abides"}` |\n| Monetary Amount | The value is a JSON object that contains `amount` and `currency` keys. The `amount` key is a positive integer representing the amount in cents. The price in the example to the right denotes €349.99.          | `"price": {"amount": 34999, "currency": "eur"}`                                   |\n\n**Lead Events**\n\nWhen submitting events for Leads, you will need to specify the Lead\'s `id`.\n\n**Metadata behaviour**\n\n- We currently limit the number of tracked metadata keys to 20 per event name. The limit counts every key ever recorded for that event name, not the keys in a single request, so it is reached cumulatively as you send more events with the same name. Once the quota is reached, we ignore any further keys we receive. The keys that count towards the quota are determined by the order in which they are sent in with the event.\n- It is not possible to change the metadata keys once the event has been sent. A new event will need to be created with the new keys and you can archive the old one.\n- There might be up to 24 hrs delay when you send a new metadata for an existing event.\n\n**Event de-duplication**\n\nThe API may detect and ignore duplicate events. Each event is uniquely identified as a combination of the following data - the Workspace identifier, the Contact external identifier, the Data Event name and the Data Event created time. As a result, it is **strongly recommended** to send a second granularity Unix timestamp in the `created_at` field.\n\nDuplicated events are responded to using the normal `202 Accepted` code - an error is not thrown, however repeat requests will be counted against any rate limit that is in place.\n\n### HTTP API Responses\n\n- Successful responses to submitted events return `202 Accepted` with an empty body.\n- Unauthorised access will be rejected with a `401 Unauthorized` or `403 Forbidden` response code.\n- Events sent about users that cannot be found will return a `404 Not Found`.\n- Event lists containing duplicate events will have those duplicates ignored.\n- Server errors will return a `500` response code and may contain an error message in the body.\n\nRequires the `write_events` OAuth scope.\n\n',
  operationId: 'createDataEvent',
  request: {
    headers: z.object({
      'Intercom-Version': IntercomVersionSchema.openapi({
        param: {
          name: 'Intercom-Version',
          in: 'header',
          schema: { $ref: '#/components/schemas/intercom_version' },
          required: false,
        },
      }).exactOptional(),
    }),
    body: { content: { 'application/json': { schema: CreateDataEventRequestSchema } } },
  },
  responses: {
    202: { description: 'successful' },
    400: {
      description: 'Bad Request',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            'Missing a required field': {
              value: {
                type: 'error.list',
                request_id: '5d0c8e27-3a91-4f6b-b2d4-7e18c9a06f53',
                errors: [{ code: 'parameter_not_found', message: 'missing data parameter' }],
              },
            },
            'Null event name': {
              value: {
                type: 'error.list',
                request_id: '9b1f3c40-5d2a-4e7b-8c16-a3d9e0f51b24',
                errors: [{ code: 'parameter_not_found', message: 'missing event_name parameter' }],
              },
            },
            'Metadata is not an object': {
              value: {
                type: 'error.list',
                request_id: 'c4e07a19-62b8-4d35-91fa-70e2b6c38d5f',
                errors: [{ code: 'type_mismatch', message: 'event metadata must be an object' }],
              },
            },
            'Bad type parameter': {
              value: {
                type: 'error.list',
                request_id: '71d3b8e5-0c46-4a92-bf27-5e8a1d60c93b',
                errors: [{ code: 'parameter_invalid', message: 'bad type parameter' }],
              },
            },
          },
        },
      },
    },
    401: {
      description: 'Unauthorized',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            Unauthorized: {
              value: {
                type: 'error.list',
                request_id: '212c8206-e7a6-44c8-8f27-5f0ad7f1d243',
                errors: [{ code: 'unauthorized', message: 'Access Token Invalid' }],
              },
            },
            'Token lacks required scope': {
              value: {
                type: 'error.list',
                request_id: '0e5a9c62-3b71-4f84-ad19-6c7e2b05f4a8',
                errors: [
                  { code: 'token_unauthorized', message: 'Not authorized to access resource' },
                ],
              },
            },
          },
        },
      },
    },
    404: {
      description: 'Contact not found',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            'User not found': {
              value: {
                type: 'error.list',
                request_id: '2b8f6d13-47ca-4e09-9d52-f1a63c0e78b5',
                errors: [{ code: 'not_found', message: 'User Not Found' }],
              },
            },
            'Lead not found': {
              value: {
                type: 'error.list',
                request_id: '6a2c91e7-8d40-4b15-a3f6-9e0b72d5c814',
                errors: [{ code: 'not_found', message: 'Lead Not Found' }],
              },
            },
          },
        },
      },
    },
    422: {
      description: 'Unprocessable entity',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            'Event name too long': {
              value: {
                type: 'error.list',
                request_id: '4f1e7b03-9c25-4d6a-82be-13a0c5d9e672',
                errors: [
                  {
                    code: 'parameter_invalid',
                    message: 'invalid event name length; use up to 100 characters',
                  },
                ],
              },
            },
            'Metadata too long': {
              value: {
                type: 'error.list',
                request_id: '8c40a5f2-1e69-4730-b8d4-27f5e1c06a93',
                errors: [
                  {
                    code: 'parameter_invalid',
                    message: 'invalid event metadata length; use up to 65535 characters',
                  },
                ],
              },
            },
            'Invalid timestamp': {
              value: {
                type: 'error.list',
                request_id: 'd57b2e91-6043-4c8f-a12d-3b9e07f45c68',
                errors: [
                  {
                    code: 'parameter_invalid',
                    message: 'invalid timestamp format; please use seconds since epoch',
                  },
                ],
              },
            },
          },
        },
      },
    },
  },
})

