export const getCallsRoute = createRoute({
  method: 'get',
  path: '/calls',
  tags: ['Calls'],
  summary: 'List all calls',
  description:
    'Retrieve a paginated list of calls.\n\nRequires the `read_conversations` OAuth scope.\n',
  operationId: 'listCalls',
  request: {
    headers: z.object({
      'Intercom-Version': IntercomVersionSchema.openapi({
        param: {
          name: 'Intercom-Version',
          in: 'header',
          schema: { $ref: '#/components/schemas/intercom_version' },
          required: false,
        },
      }).exactOptional(),
    }),
    query: z.object({
      page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'page',
            in: 'query',
            required: false,
            description: 'The page of results to fetch. Defaults to first page',
            example: 1,
            schema: { type: 'integer' },
          },
        }),
      per_page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(1).max(25),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'per_page',
            in: 'query',
            required: false,
            description:
              'How many results to display per page. Defaults to 25. Must be between 1 and 25. A value outside that range returns a 400 error.',
            example: 25,
            schema: { type: 'integer', minimum: 1, maximum: 25 },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'successful',
      content: {
        'application/json': {
          schema: CallListSchema,
          examples: {
            successful: {
              value: {
                type: 'list',
                data: [],
                total_count: 0,
                pages: { type: 'pages', page: 1, per_page: 25, total_pages: 0 },
              },
            },
          },
        },
      },
    },
    400: {
      description: 'Bad Request',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            'Per page too large': {
              value: {
                type: 'error.list',
                request_id: '5d1f7a3c-8e2b-4c64-9a0f-1b7e3c2d4f90',
                errors: [{ code: 'parameter_invalid', message: 'Per Page is too big' }],
              },
            },
            'Per page too small': {
              value: {
                type: 'error.list',
                request_id: '0c9b6e41-27d3-4a85-b1f6-6e8a3d5c7b12',
                errors: [{ code: 'parameter_invalid', message: 'Per Page is too small' }],
              },
            },
          },
        },
      },
    },
    401: {
      description: 'Unauthorized',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            Unauthorized: {
              value: {
                type: 'error.list',
                request_id: 'e097e446-9ae6-44a8-8e13-2bf3008b87ef',
                errors: [{ code: 'unauthorized', message: 'Access Token Invalid' }],
              },
            },
            'Token lacks required scope': {
              value: {
                type: 'error.list',
                request_id: 'a3e5b8e2-1234-5678-9abc-def012345678',
                errors: [
                  { code: 'token_unauthorized', message: 'Not authorized to access resource' },
                ],
              },
            },
          },
        },
      },
    },
  },
})

