export const postCallsSearchRoute = createRoute({
  method: 'post',
  path: '/calls/search',
  tags: ['Calls'],
  summary: 'List calls with transcripts',
  description:
    'Retrieve calls by a list of conversation ids and include transcripts when available.\nA maximum of 20 `conversation_ids` can be provided. If none are provided or more than 20 are provided, a 400 error is returned.\n\nRequires the `read_conversations` OAuth scope.\n',
  operationId: 'listCallsWithTranscripts',
  request: {
    headers: z.object({
      'Intercom-Version': IntercomVersionSchema.openapi({
        param: {
          name: 'Intercom-Version',
          in: 'header',
          schema: { $ref: '#/components/schemas/intercom_version' },
          required: false,
        },
      }).exactOptional(),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              conversation_ids: z
                .array(z.string())
                .min(1)
                .max(20)
                .openapi({
                  description: 'A list of conversation ids to fetch calls for. Maximum 20.',
                }),
            })
            .openapi({ required: ['conversation_ids'] }),
          examples: {
            example: { value: { conversation_ids: ['64619700005694', '64619700005695'] } },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'successful',
      content: {
        'application/json': {
          schema: z
            .object({
              type: z.string().exactOptional().openapi({ example: 'list' }),
              data: z
                .array(
                  CallSchema.and(
                    z
                      .object({
                        transcript: z
                          .array(z.looseObject({}))
                          .exactOptional()
                          .openapi({
                            description:
                              'The call transcript if available, otherwise an empty array.',
                          }),
                        transcript_status: z
                          .string()
                          .nullable()
                          .exactOptional()
                          .openapi({ description: 'The status of the transcript if available.' }),
                      })
                      .openapi({ required: [] }),
                  ),
                )
                .exactOptional(),
            })
            .openapi({ required: [] }),
          examples: {
            successful: {
              value: {
                type: 'list',
                data: [
                  {
                    type: 'call',
                    id: '123',
                    conversation_id: '64619700005694',
                    transcript: [
                      {
                        start_time: '0.0',
                        end_time: '3.00',
                        speaker_label: 'Teammate 1',
                        speaker: 'Teammate 1',
                        content: 'Hello, thanks for calling. How can I help today?',
                        speaker_type: 'admin',
                        speaker_id: '789',
                      },
                    ],
                    transcript_status: 'completed',
                  },
                ],
              },
            },
          },
        },
      },
    },
    400: {
      description: 'Bad Request',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            too_many_ids: {
              value: {
                type: 'error.list',
                errors: [
                  {
                    code: 'conversation_id_limit_exceeded',
                    message: 'A list of up to 20 conversation IDs is required',
                  },
                ],
              },
            },
          },
        },
      },
    },
    401: {
      description: 'Unauthorized',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            Unauthorized: {
              value: {
                type: 'error.list',
                errors: [{ code: 'unauthorized', message: 'Access Token Invalid' }],
              },
            },
            'Token lacks required scope': {
              value: {
                type: 'error.list',
                request_id: 'a3e5b8e2-1234-5678-9abc-def012345678',
                errors: [
                  { code: 'token_unauthorized', message: 'Not authorized to access resource' },
                ],
              },
            },
          },
        },
      },
    },
  },
})

