export const getTeamsTeamIdMetricsRoute = createRoute({
  method: 'get',
  path: '/teams/{team_id}/metrics',
  tags: ['Teams'],
  summary: 'Retrieve team metrics',
  description:
    'Returns real-time activity metrics for admins in the specified team. For each admin, the response includes counts of open, idle, and snoozed conversations.\n\nThis endpoint requires the `realtime_monitoring` feature to be enabled for your workspace.\n',
  operationId: 'getTeamMetrics',
  request: {
    headers: z.object({
      'Intercom-Version': IntercomVersionSchema.openapi({
        param: {
          name: 'Intercom-Version',
          in: 'header',
          schema: { $ref: '#/components/schemas/intercom_version' },
          required: false,
        },
      }).exactOptional(),
    }),
    params: z.object({
      team_id: z
        .string()
        .openapi({
          param: {
            name: 'team_id',
            in: 'path',
            required: true,
            description:
              'The unique identifier of the team to retrieve metrics for. Use `GET /teams` to list available team IDs.',
            example: '42',
            schema: { type: 'string' },
          },
        }),
    }),
    query: z.object({
      idle_threshold: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .default(1800)
        .exactOptional()
        .openapi({
          param: {
            name: 'idle_threshold',
            in: 'query',
            required: false,
            description:
              'The number of seconds after which an open conversation is considered idle. Clamped to the range 1–86400. Defaults to 1800 (30 minutes).',
            schema: { type: 'integer', default: 1800, example: 1800 },
          },
          example: 1800,
        }),
    }),
  },
  responses: {
    200: {
      description: 'Successful response',
      content: {
        'application/json': {
          schema: TeamMetricListSchema,
          examples: {
            successful_response: {
              value: {
                type: 'team_metric.list',
                data: [
                  { type: 'team_metric', admin_id: '123', open: 5, idle: 2, snoozed: 1 },
                  { type: 'team_metric', admin_id: '456', open: 3, idle: 0, snoozed: 2 },
                ],
              },
            },
          },
        },
      },
    },
    401: UnauthorizedResponse,
    403: {
      description: 'Feature not enabled',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            feature_disabled: {
              value: {
                type: 'error.list',
                request_id: 'req-456',
                errors: [
                  {
                    code: 'api_plan_restricted',
                    message: 'Real-time monitoring is not enabled for your workspace.',
                  },
                ],
              },
            },
          },
        },
      },
    },
    404: {
      description: 'Team not found',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            team_not_found: {
              value: {
                type: 'error.list',
                request_id: 'req-789',
                errors: [{ code: 'team_not_found', message: 'Team not found' }],
              },
            },
          },
        },
      },
    },
  },
})

