export const getFinVoiceCollectIdRoute = createRoute({
  method: 'get',
  path: '/fin_voice/collect/{id}',
  tags: ['Calls'],
  summary: 'Collect Fin Voice call by ID',
  description:
    'Retrieve information about a Fin Voice call using the external reference ID.\n\nRequires the `read_conversations` OAuth scope.\n',
  operationId: 'collectFinVoiceCallById',
  request: {
    headers: z.object({
      'Intercom-Version': IntercomVersionSchema.openapi({
        param: {
          name: 'Intercom-Version',
          in: 'header',
          schema: { $ref: '#/components/schemas/intercom_version' },
          required: false,
        },
      }).exactOptional(),
    }),
    params: z.object({
      id: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .openapi({
          param: {
            name: 'id',
            in: 'path',
            required: true,
            description: 'The external reference ID',
            schema: { type: 'integer' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'successful',
      content: { 'application/json': { schema: AiCallResponseSchema } },
    },
    404: {
      description: 'not found - external reference not found or not matched',
      content: { 'application/json': { schema: ErrorSchema } },
    },
    default: {
      description: 'Unexpected error',
      content: { 'application/json': { schema: ErrorSchema } },
    },
  },
})

