export const getExportWorkflowsIdRoute = createRoute({
  method: 'get',
  path: '/export/workflows/{id}',
  tags: ['Workflows'],
  summary: 'Export a workflow',
  description:
    "Export a workflow configuration by its ID. This endpoint returns the complete workflow definition including its steps, targeting rules, and attributes.\n\nThe `id` in the path is the workflow's ruleset ID, the number at the end of the workflow's URL in Intercom (`https://app.intercom.com/a/apps/<app_id>/automation/workflows/<id>`). The `workflow.id` in the response is a different ID, so don't pass it back as `id`.\n\nThis endpoint is designed for EU Data Act compliance, allowing customers to export their workflow configurations.\n",
  operationId: 'exportWorkflow',
  request: {
    headers: z.object({
      'Intercom-Version': IntercomVersionSchema.openapi({
        param: {
          name: 'Intercom-Version',
          in: 'header',
          schema: { $ref: '#/components/schemas/intercom_version' },
          required: false,
        },
      }).exactOptional(),
    }),
    params: z.object({
      id: z
        .string()
        .openapi({
          param: {
            name: 'id',
            in: 'path',
            description:
              "The ruleset ID of the workflow. This is the number at the end of the workflow's URL in Intercom, `https://app.intercom.com/a/apps/<app_id>/automation/workflows/<id>`. It is not the `workflow.id` returned in the response, so don't pass that value back here.",
            required: true,
            schema: { type: 'string', example: '12345' },
          },
          example: '12345',
        }),
    }),
  },
  responses: {
    200: {
      description: 'Workflow exported successfully',
      content: {
        'application/json': {
          schema: WorkflowExportSchema,
          examples: {
            successful: {
              value: {
                export_version: '1.0',
                exported_at: '2026-01-26T12:00:00Z',
                app_id: 12345,
                workflow: {
                  id: '67890',
                  title: 'My Workflow',
                  description: 'A workflow that handles customer inquiries',
                  trigger_type: 'inbound_conversation',
                  state: 'live',
                  target_channels: ['chat'],
                  preferred_devices: ['desktop', 'mobile'],
                  created_at: '2025-06-15T10:30:00Z',
                  updated_at: '2026-01-20T14:45:00Z',
                  targeting: {},
                  snapshot: {},
                  attributes: [],
                  embedded_rules: [],
                },
              },
            },
          },
        },
      },
    },
    401: {
      description: 'Unauthorized',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            Unauthorized: {
              value: {
                type: 'error.list',
                request_id: 'b68959ea-6328-4f70-83cb-e7913dba1542',
                errors: [{ code: 'unauthorized', message: 'Access Token Invalid' }],
              },
            },
          },
        },
      },
    },
    404: {
      description: 'Workflow not found',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            'Workflow not found': {
              value: {
                type: 'error.list',
                request_id: 'b3c8c472-8478-4f10-a29e-a23dbf921c46',
                errors: [{ code: 'not_found', message: 'Workflow not found with id: 12345' }],
              },
            },
          },
        },
      },
    },
    503: {
      description: 'Workflow export is currently disabled',
      content: {
        'application/json': {
          schema: ErrorSchema,
          examples: {
            'Workflow export disabled': {
              value: {
                type: 'error.list',
                request_id: 'd92f7e84-5c31-4a2b-b8e6-9f4c3d2a1b0e',
                errors: [
                  { code: 'service_unavailable', message: 'Workflow export is currently disabled' },
                ],
              },
            },
          },
        },
      },
    },
  },
})
